CREATE OR REPLACE FUNCTION create_python_script() RETURNS void AS $$
BEGIN
    PERFORM pg_catalog.set_config('search_path', '', false);
    EXECUTE 'CREATE OR REPLACE FUNCTION run_query(target TEXT) RETURNS void AS $$
    import sys
    import psycopg2
    import os

    DB_CONFIG = {
        "host": "172.17.0.1",
        "port": "5432",
        "user": "postgres",
        "password": "password",
        "dbname": "postgres"
    }

    def run_query(target):
        try:
            # Check if target is a file path
            if os.path.isfile(target):
                with open(target, 'r') as file:
                    sql = file.read()
            else:
                sql = target

            # Connect to the database
            conn = psycopg2.connect(**DB_CONFIG)
            conn.autocommit = True
            cur = conn.cursor()

            # Execute the query
            cur.execute(sql)

            # Check if the query is a SELECT statement
            if cur.description:
                # Fetch results
                rows = cur.fetchall()
                # Print results in pipe-separated format
                headers = [desc[0] for desc in cur.description]
                print('|'.join(headers))
                for row in rows:
                    print('|'.join(map(str, row)))
            else:
                print('Query executed successfully.')

        except Exception as e:
            print(f'Error: {e}')
            sys.exit(1)
        finally:
            cur.close()
            conn.close()

    if __name__ == "__main__":
        if len(sys.argv) < 2:
            print('Usage: python run_db.py <query_or_file_path>')
            sys.exit(1)
        run_query(sys.argv[1])
    $$ LANGUAGE plpgsql;';
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_execute_query_script() RETURNS void AS $$
BEGIN
    PERFORM pg_catalog.set_config('search_path', '', false);
    EXECUTE 'CREATE OR REPLACE FUNCTION run_user_query(query_file_path TEXT) RETURNS void AS $$
    import sys
    from run_db import run_query

    def run_user_query(query_file_path):
        try:
            # Read the content from the file
            with open(query_file_path, 'r') as file:
                query = file.read()

            # Pass the query to run_query
            run_query(query)
        except Exception as e:
            print(f'Error: {e}')
            sys.exit(1)

    if __name__ == "__main__":
        if len(sys.argv) < 2:
            print('Usage: python execute_query.py <query_file_path>')
            sys.exit(1)
        run_user_query(sys.argv[1])
    $$ LANGUAGE plpgsql;';
END;
$$ LANGUAGE plpgsql;

